from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Table, LongTable, TableStyle, KeepTogether, Spacer
from reportlab.lib.colors import HexColor
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

OUT='output/pdf/Resumen-Unidad-1-Almacenamiento.pdf'
NAVY=HexColor('#17324D'); BLUE=HexColor('#246A8D'); PALE=HexColor('#EAF2F6'); INK=HexColor('#24323D'); LIGHT=HexColor('#D6E5ED')
pdfmetrics.registerFont(TTFont('Arial','C:/Windows/Fonts/arial.ttf'))
pdfmetrics.registerFont(TTFont('Arial-Bold','C:/Windows/Fonts/arialbd.ttf'))
pdfmetrics.registerFont(TTFont('Arial-Italic','C:/Windows/Fonts/ariali.ttf'))
pdfmetrics.registerFont(TTFont('Arial-BoldItalic','C:/Windows/Fonts/arialbi.ttf'))
pdfmetrics.registerFontFamily('Arial',normal='Arial',bold='Arial-Bold',italic='Arial-Italic',boldItalic='Arial-BoldItalic')
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='TitleX',parent=s['Title'],fontName='Arial-Bold',fontSize=20,leading=24,textColor=NAVY,alignment=1,spaceAfter=3))
s.add(ParagraphStyle(name='SubX',parent=s['Normal'],fontName='Arial',fontSize=8.8,leading=11,textColor=BLUE,alignment=1,spaceAfter=8))
s.add(ParagraphStyle(name='HeadX',parent=s['Heading2'],fontName='Arial-Bold',fontSize=12,leading=14,textColor=NAVY,spaceBefore=5,spaceAfter=3,keepWithNext=True))
s.add(ParagraphStyle(name='SubHeadX',parent=s['Heading3'],fontName='Arial-Bold',fontSize=9.4,leading=11.5,textColor=BLUE,spaceBefore=3,spaceAfter=2,keepWithNext=True))
s.add(ParagraphStyle(name='BodyX',parent=s['BodyText'],fontName='Arial',fontSize=8.7,leading=11,textColor=INK,spaceAfter=3))
s.add(ParagraphStyle(name='TinyX',parent=s['BodyText'],fontName='Arial',fontSize=7.8,leading=9.5,textColor=INK,spaceAfter=1))
s.add(ParagraphStyle(name='CallX',parent=s['BodyText'],fontName='Arial',fontSize=8.5,leading=10.8,textColor=NAVY,spaceAfter=0))
def P(x,style='BodyX'):
 para=Paragraph(x,s[style])
 if style != 'CallX': return para
 box=Table([[para]],colWidths=[174*mm],hAlign='LEFT')
 box.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),PALE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
 box.spaceBefore=2; box.spaceAfter=4
 return box
def H(x): return P(x,'HeadX')
def SH(x): return P(x,'SubHeadX')
def B(x): return P('• '+x,'BodyX')
def footer(c,d):
 c.saveState(); c.setStrokeColor(HexColor('#D7E1E8')); c.line(18*mm,14*mm,192*mm,14*mm); c.setFont('Arial',7.5); c.setFillColor(HexColor('#607482')); c.drawString(18*mm,9*mm,'BASES DE DATOS | UNIDAD 1'); c.drawRightString(192*mm,9*mm,str(d.page)); c.restoreState()
def table(rows,widths):
 t=LongTable(rows,colWidths=widths,repeatRows=1,splitByRow=1,hAlign='LEFT'); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),LIGHT),('TEXTCOLOR',(0,0),(-1,0),NAVY),('GRID',(0,0),(-1,-1),.35,HexColor('#CAD7DF')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,PALE]),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)])); return t
story=[P('UNIDAD 1: ALMACENAMIENTO DE LA INFORMACIÓN','TitleX'),P('Resumen de los 9 apartados principales | Guía breve pero completa para estudiar','SubX'),P('<b>Idea general.</b> Toda aplicación necesita guardar, localizar y proteger datos. La unidad explica cómo se pasa de ficheros independientes a bases de datos gestionadas, distribuidas y analizadas.','CallX'),H('1. Ficheros de información'),P('<b>Fichero:</b> conjunto de datos relacionados y estructurados. Se compone de <b>registros</b> (cada elemento) y <b>campos</b> (sus propiedades). Una <b>clave</b> identifica registros. El sistema operativo mueve datos entre memoria y soporte en <b>bloques</b>; el número de registros lógicos que caben en un bloque es el factor de blocaje.'),P('<b>Tipos por función:</b> permanentes: maestros (situación actual), constantes (referencia que cambia poco) e históricos (estados pasados). Temporales: intermedios (resultados que usa otro proceso), de maniobra (apoyo cuando falta memoria) y de resultados (salida). Los registros pueden ser de longitud fija, variable, delimitados o indefinida.'),P('<b>Soportes:</b> acceso secuencial (cinta: hay que recorrer los datos previos) y acceso directo (discos/SSD: se salta a la posición). Para elegir organización se valoran capacidad, actividad de consulta/modificación, volatilidad (altas y bajas) y crecimiento.'),table([[P('<b>Organización</b>','TinyX'),P('<b>Funcionamiento, ventajas y límites</b>','TinyX')],[P('Secuencial','TinyX'),P('Registros contiguos en orden. Simple y aprovecha el espacio; buscar requiere recorrerlo y actualizarlo suele exigir crear otro fichero.','TinyX')],[P('Secuencial encadenada','TinyX'),P('Un puntero enlaza cada registro con el siguiente. Facilita inserciones y borrados, pero las búsquedas siguen un recorrido secuencial.','TinyX')],[P('Secuencial indexada','TinyX'),P('Área de datos ordenada por clave, índice de claves y direcciones, más área de desbordamiento. Permite acceso secuencial y directo, a costa de espacio adicional.','TinyX')],[P('Directa o aleatoria','TinyX'),P('Se localiza mediante posición o clave; rápida y actualizable en el propio fichero. El hashing calcula direcciones y puede generar colisiones, que se resuelven buscando otro hueco o con área de desbordamiento.','TinyX')]], [38*mm,136*mm]),P('<b>Problemas de gestionar solo ficheros:</b> duplicidad e incoherencia; dependencia entre programas y formato de datos; consultas nuevas costosas; datos aislados; concurrencia, integridad y seguridad difíciles. Estos problemas impulsaron las BD y los SGBD.','CallX'),H('2. Bases de datos'),P('Una <b>BD</b> es una colección de datos lógicamente relacionados, con una descripción común y organizada para reducir redundancia y permitir acceso eficiente. El <b>SGBD</b> es el software que define, construye y manipula esa BD: BD son los datos; SGBD es quien los administra.'),P('Las BD aparecieron para separar los datos de los programas y compartir información de forma controlada. El catálogo o diccionario de datos guarda <b>metadatos</b> (descripción de tablas, campos, relaciones, índices y permisos).'),SH('Ventajas principales'),B('Acceso compartido y concurrente, con vistas distintas según el usuario.'),B('Redundancia controlada; más consistencia e integridad.'),B('Seguridad y confidencialidad mediante usuarios, roles y permisos.'),B('Independencia física: cambios en el almacenamiento no obligan a cambiar las aplicaciones.'),B('Independencia lógica: cambios en el diseño pueden aislarse de las vistas y programas.'),B('Copias y recuperación ante fallos, consultas directas e interfaces de alto nivel.'),SH('Quién trabaja con una BD'),P('<b>Administrador (DBA):</b> almacenamiento, índices, seguridad y acceso. <b>Diseñador:</b> estructura, relaciones y restricciones. <b>Programador:</b> crea aplicaciones que consultan y actualizan. <b>Usuario final:</b> utiliza la información. Se usan, por ejemplo, en banca, universidades, sanidad, administración, telecomunicaciones, turismo y bibliotecas.'),SH('Dónde se almacena'),P('<b>HDD:</b> discos magnéticos mecánicos. <b>SSD:</b> memoria flash, acceso rápido. <b>Cinta:</b> acceso secuencial, económica y útil para copias masivas. <b>RAID:</b> varios discos coordinados: RAID 0 mejora velocidad sin redundancia; RAID 1 duplica datos; RAID 5 distribuye datos y paridad y tolera el fallo de un disco; RAID 6 tolera dos. <b>NAS</b> comparte archivos por red; <b>SAN</b> ofrece almacenamiento en bloques a servidores. La <b>nube</b> ofrece acceso remoto y capacidad flexible, pero depende de la conexión y del proveedor.'),H('3. Evolución de los modelos de BD'),P('Un modelo de datos define cómo se organizan los datos, las relaciones y las restricciones.'),table([[P('<b>Modelo</b>','TinyX'),P('<b>Estructura / cuándo conviene recordarlo</b>','TinyX')],[P('Jerárquico','TinyX'),P('Árbol padre-hijo: cada hijo tiene un único padre. Claro y rápido, pero rígido; hoy está en desuso.','TinyX')],[P('En red','TinyX'),P('Registros conectados por enlaces; permite varios padres y relaciones muchos a muchos, aunque es más complejo.','TinyX')],[P('Relacional','TinyX'),P('Tablas: filas/tuplas y columnas/atributos; claves primarias identifican filas. Flexible y muy extendido; se consulta con SQL.','TinyX')],[P('Orientado a objetos','TinyX'),P('Objetos, clases, propiedades y operaciones; incorpora encapsulación, herencia y polimorfismo. Adecuado para datos complejos, pero no sustituyó al relacional.','TinyX')],[P('Documental','TinyX'),P('Documentos semiestructurados (p. ej. JSON), normalmente sin esquema rígido. Flexible para aplicaciones web; ejemplo: MongoDB.','TinyX')]], [39*mm,135*mm]),P('<b>Otros:</b> objeto-relacional combina tablas con funciones de objetos; deductivo deriva hechos mediante reglas; multidimensional organiza datos en cubos para análisis; transaccional prioriza operaciones fiables que se completan o se cancelan.','BodyX'),H('4. Sistemas gestores de bases de datos (SGBD)'),P('Un SGBD es un conjunto de programas, lenguajes y procedimientos que permite definir, construir y manipular una BD con eficiencia y seguridad. Gestiona grandes volúmenes, abstrae el almacenamiento, reduce redundancia, valida integridad, comparte accesos y ofrece copias y recuperación.'),SH('Funciones y lenguajes'),P('<b>DDL (definición):</b> crea y modifica estructuras, relaciones, restricciones y vistas. <b>DML (manipulación):</b> consulta, inserta, modifica y borra datos. <b>DCL (control):</b> gestiona usuarios, permisos y seguridad. En BD relacionales, SQL reúne instrucciones de estos tipos.'),SH('Componentes'),P('Lenguajes de BD; diccionario de datos con metadatos; gestor central que coordina operaciones; usuarios con distintos privilegios; y herramientas de administración, informes, formularios y desarrollo.'),SH('Arquitectura ANSI/SPARC'),P('<b>Interno/físico:</b> cómo se guardan bloques e índices. <b>Conceptual/lógico:</b> estructura global, entidades, relaciones y restricciones. <b>Externo:</b> vistas específicas para usuarios/aplicaciones. Hay un esquema interno y uno conceptual, y puede haber varios externos. Independencia física = cambiar almacenamiento sin afectar el diseño lógico; lógica = cambiar el diseño global procurando no afectar vistas/programas.'),SH('Clasificaciones de SGBD'),P('Pueden ser monousuario o multiusuario; centralizados o distribuidos (homogéneos si usan el mismo SGBD, heterogéneos si usan varios); de propósito general o específico; y gratuitos o de pago.'),H('5. SGBD comerciales y libres'),P('<b>Comerciales citados en la unidad:</b> Oracle, MySQL Standard/Enterprise, DB2, Informix y Microsoft SQL Server; también Access, Interbase, dBase y FoxPro. <b>Libres/de código abierto:</b> MySQL Community, MariaDB, PostgreSQL, Firebird, Apache Derby y SQLite.'),P('La elección depende del volumen y carga, sistema operativo, presupuesto, plazos, compatibilidad y necesidades de seguridad y mantenimiento. No existe un SGBD óptimo para todos los proyectos.'),H('6. Bases de datos centralizadas'),P('El SGBD y los datos residen en un único ordenador o plataforma. Facilita administración, control, integridad y evita duplicaciones por copias dispersas. Puede ser más sencillo y económico de mantener. Sus límites: capacidad ligada a una máquina, concentración de la carga y punto único de fallo; una avería puede dejar sin servicio o dificultar la recuperación.'),H('7. Bases de datos distribuidas'),P('Una <b>BD distribuida</b> es un conjunto de bases lógicamente relacionadas almacenadas en nodos conectados por una red. El SGBD distribuido procura que el usuario las perciba como un único sistema.'),SH('Ventajas y costes'),P('Puede repartir procesamiento, acercar datos a usuarios, escalar, permitir acceso remoto y mantener disponibilidad ante el fallo de un nodo (por ejemplo, con replicación). A cambio, requiere coordinación y sincronización, complica concurrencia y recuperación, aumenta la superficie de seguridad y puede encarecer el mantenimiento.'),P('7. Bases de datos distribuidas (continuación)','SubHeadX'),SH('Fragmentación'),P('Se divide una relación para colocar sus partes en distintos nodos. <b>Horizontal:</b> separa filas mediante criterios de selección; se reconstruye uniendo fragmentos. Puede ser primaria o derivada (esta última sigue la fragmentación de una tabla relacionada). <b>Vertical:</b> separa columnas y repite la clave primaria en cada fragmento para poder recomponer filas. <b>Mixta:</b> combina horizontal y vertical. La fragmentación funcional agrupa los datos según las funciones habituales.'),P('<b>Tres reglas:</b> completitud (no perder datos); reconstrucción (poder recomponer la relación original); disyunción (evitar duplicar datos, salvo claves necesarias). Se busca un equilibrio que mejore consultas y distribución sin fragmentar en exceso.','CallX'),H('8. Protección de datos: RGPD y LOPDGDD'),P('Dato personal es información sobre una persona física identificada o identificable. Los datos sensibles incluyen origen racial o étnico, opiniones políticas, religión, afiliación sindical, genética, biometría identificativa, salud y vida u orientación sexual. La protección de datos es un derecho fundamental.'),P('El <b>RGPD</b> (Reglamento UE 2016/679) fija el marco común europeo. La <b>LOPDGDD</b> (Ley Orgánica 3/2018) lo complementa en España y recoge derechos digitales. La normativa se centra en cómo se tratan los datos, no solo en los ficheros donde se guardan.'),SH('Principios que hay que saber'),P('Licitud, lealtad y transparencia; finalidad determinada; minimización (solo lo necesario); exactitud; conservación limitada; integridad y confidencialidad; y responsabilidad proactiva (poder demostrar cumplimiento).'),SH('Derechos, obligaciones y seguridad'),P('Las personas pueden ejercer acceso, rectificación, supresión, limitación, portabilidad y oposición, además de garantías ante decisiones automatizadas. La organización debe establecer una base válida para tratar datos, informar, limitar accesos, aplicar medidas técnicas y organizativas, llevar registros y evaluar riesgos cuando corresponda. Se designa DPO/DPD en ciertos supuestos, como autoridades públicas y tratamientos a gran escala de datos sensibles o monitorización sistemática. Las brechas se notifican a la autoridad en el plazo previsto (el material destaca 72 horas). La AEPD supervisa en España.'),P('<b>Medidas típicas:</b> control de acceso, autenticación, cifrado, copias de seguridad, protección física, políticas internas y acuerdos con encargados del tratamiento.','CallX'),H('9. Big Data'),P('Big Data trata volúmenes de datos tan grandes, rápidos o variados que las herramientas tradicionales no bastan. Puede combinar datos estructurados, semiestructurados y no estructurados.'),SH('Las 5 V'),P('<b>Volumen:</b> cantidad. <b>Velocidad:</b> generación y procesamiento. <b>Variedad:</b> formatos y fuentes. <b>Veracidad:</b> calidad y fiabilidad. <b>Valor:</b> utilidad obtenida del análisis.'),SH('Tipos de datos'),P('<b>Estructurados:</b> esquema fijo, habitualmente tablas; fáciles de consultar con SQL. <b>Semiestructurados:</b> etiquetas/metadatos sin tabla rígida, como XML o JSON. <b>No estructurados:</b> texto libre, documentos, imágenes, audio y vídeo; requieren procesamiento antes del análisis.'),SH('Análisis de datos'),P('<b>Descriptivo:</b> qué ocurrió. <b>Diagnóstico:</b> por qué ocurrió. <b>Predictivo:</b> qué podría ocurrir. <b>Prescriptivo:</b> qué acción conviene. Flujo típico: recopilar, almacenar, limpiar/preparar, explorar, modelar, interpretar y comunicar.'),P('Tecnologías citadas: Hadoop y HDFS para almacenamiento/procesamiento distribuido; Spark para procesamiento; bases NoSQL (p. ej., MongoDB o Cassandra) para datos flexibles; herramientas de aprendizaje automático para modelos.'),SH('Inteligencia de negocio (BI)'),P('BI aplica análisis a las necesidades de decisión de una empresa. <b>ETL</b> extrae datos de fuentes, los transforma y los carga en un <b>almacén de datos</b>. Las herramientas BI los convierten en informes y cuadros de mando. El proceso integra fuentes, analiza y visualiza resultados para apoyar decisiones. Beneficios: decisiones mejor informadas, optimización de procesos, eficiencia y detección de oportunidades. Retos: integrar fuentes, mantener calidad, proteger datos y escalar.'),]
doc=SimpleDocTemplate(OUT,pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=13*mm,bottomMargin=17*mm,title='Unidad 1: Almacenamiento de la información - Resumen',author='Resumen de estudio')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(OUT)






